def c_fin_semana_paute_75(P, ctx, mod):
    dd = ctx.get("deltaDia")
    if not dd or len(dd) < 7:
        return None
    nuevo_dd = list(dd)
    cambio = False
    for idx in (0, 6):
        val = float(nuevo_dd[idx])
        if val < 0.0:
            nuevo_dd[idx] = round(val * 0.75, 1)
            cambio = True
    if not cambio:
        return None
    ctx["deltaDia"] = nuevo_dd
    return P, ctx, {"deltaDia": nuevo_dd}

